{"type": "FUNCTION", "name": "c_lex_with_flags", "location": "/data/zhangtianrong/projects/rustc-cbi/graphlocator_gcc/gcc/gcc/c-family/c-lex.cc", "content": "non-NULL.  */

enum cpp_ttype
c_lex_with_flags (tree *value, location_t *loc, unsigned char *cpp_flags,
		  int lex_flags)
{
  const cpp_token *tok;
  enum cpp_ttype type;
  unsigned char add_flags = 0;
  enum overflow_type overflow = OT_NONE;

  timevar_push (TV_CPP);
 retry:
  tok = get_token (parse_in, loc);
  type = tok->type;

 retry_after_at:
  switch (type)
    {
    case CPP_PADDING:
      goto retry;

    case CPP_NAME:
      *value = HT_IDENT_TO_GCC_IDENT (HT_NODE (tok->val.node.node));
      break;

    case CPP_NUMBER:
      {
	const char *suffix = NULL;
	unsigned int flags = cpp_classify_number (parse_in, tok, &suffix, *loc);

	switch (flags & CPP_N_CATEGORY)
	  {
	  case CPP_N_INVALID:
	    /* cpplib has issued an error.  */
	    *value = error_mark_node;
	    break;

	  case CPP_N_INTEGER:
	    /* C++ uses '0' to mark virtual functions as pure.
	       Set PURE_ZERO to pass this information to the C++ parser.  */
	    if (tok->val.str.len == 1 && *tok->val.str.text == '0')
	      add_flags = PURE_ZERO | DECIMAL_INT;
	    else if ((flags & CPP_N_INTEGER) && (flags & CPP_N_DECIMAL))
	      /* -Wxor-used-as-pow is only active for LHS of ^ expressed
		 as a decimal integer. */
	      add_flags = DECIMAL_INT;
	    *value = interpret_integer (tok, flags, &overflow);
	    break;

	  case CPP_N_FLOATING:
	    *value = interpret_float (tok, flags, suffix, &overflow);
	    break;

	  default:
	    gcc_unreachable ();
	  }

	if (flags & CPP_N_USERDEF)
	  {
	    char *str;
	    tree literal;
	    tree suffix_id = get_identifier (suffix);
	    int len = tok->val.str.len - strlen (suffix);
	    /* If this is going to be used as a C string to pass to a
	       raw literal operator, we need to add a trailing NUL.  */
	    tree num_string = build_string (len + 1,
					    (const char *) tok->val.str.text);
	    TREE_TYPE (num_string) = char_array_type_node;
	    num_string = fix_string_type (num_string);
	    str = CONST_CAST (char *, TREE_STRING_POINTER (num_string));
	    str[len] = '\0';
	    literal = build_userdef_literal (suffix_id, *value, overflow,
					     num_string);
	    *value = literal;
	  }
      }
      break;

    case CPP_ATSIGN:
      /* An @ may give the next token special significance in Objective-C.  */
      if (c_dialect_objc ())
	{
	  location_t atloc = *loc;
	  location_t newloc;

	retry_at:
	  tok = get_token (parse_in, &newloc);
	  type = tok->type;
	  switch (type)
	    {
	    case CPP_PADDING:
	      goto retry_at;

	    case CPP_STRING:
	    case CPP_WSTRING:
	    case CPP_STRING16:
	    case CPP_STRING32:
	    case CPP_UTF8STRING:
	      type = lex_string (tok, value, true, true);
	      break;

	    case CPP_NAME:
	      *value = HT_IDENT_TO_GCC_IDENT (HT_NODE (tok->val.node.node));
	      if (OBJC_IS_AT_KEYWORD (C_RID_CODE (*value))
		  || OBJC_IS_CXX_KEYWORD (C_RID_CODE (*value)))
		{
		  type = CPP_AT_NAME;
		  /* Note the complication: if we found an OBJC_CXX
		     keyword, for example, 'class', we will be
		     returning a token of type CPP_AT_NAME and rid
		     code RID_CLASS (not RID_AT_CLASS).  The language
		     parser needs to convert that to RID_AT_CLASS.
		     However, we've now spliced the '@' together with the
		     keyword that follows; Adjust the location so that we
		     get a source range covering the composite.
		  */
	         *loc = make_location (atloc, atloc, newloc);
		  break;
		}
	      /* FALLTHROUGH */

	    default:
	      /* ... or not.  */
	      error_at (atloc, "stray %<@%> in program");
	      *loc = newloc;
	      goto retry_after_at;
	    }
	  break;
	}

      /* FALLTHROUGH */
    case CPP_HASH:
    case CPP_PASTE:
      {
	unsigned char name[8];

	*cpp_spell_token (parse_in, tok, name, true) = 0;

	error_at (*loc, "stray %qs in program", name);
      }

      goto retry;

    case CPP_OTHER:
      {
	cppchar_t c = tok->val.str.text[0];

	if (c == '"' || c == '\'')
	  error_at (*loc, "missing terminating %c character", (int) c);
	else if (ISGRAPH (c))
	  error_at (*loc, "stray %qc in program", (int) c);
	else
	  {
	    rich_location rich_loc (line_table, *loc);
	    rich_loc.set_escape_on_output (true);
	    error_at (&rich_loc, "stray %<\\%o%> in program", (int) c);
	  }
      }
      goto retry;

    case CPP_CHAR_USERDEF:
    case CPP_WCHAR_USERDEF:
    case CPP_CHAR16_USERDEF:
    case CPP_CHAR32_USERDEF:
    case CPP_UTF8CHAR_USERDEF:
      {
	tree literal;
	cpp_token temp_tok = *tok;
	const char *suffix = cpp_get_userdef_suffix (tok);
	temp_tok.val.str.len -= strlen (suffix);
	temp_tok.type = cpp_userdef_char_remove_type (type);
	literal = build_userdef_literal (get_identifier (suffix),
					 lex_charconst (&temp_tok),
					 OT_NONE, NULL_TREE);
	*value = literal;
      }
      break;

    case CPP_CHAR:
    case CPP_WCHAR:
    case CPP_CHAR16:
    case CPP_CHAR32:
    case CPP_UTF8CHAR:
      *value = lex_charconst (tok);
      break;

    case CPP_STRING_USERDEF:
    case CPP_WSTRING_USERDEF:
    case CPP_STRING16_USERDEF:
    case CPP_STRING32_USERDEF:
    case CPP_UTF8STRING_USERDEF:
      {
	tree literal, string;
	const char *suffix = cpp_get_userdef_suffix (tok);
	string = build_string (tok->val.str.len - strlen (suffix),
			       (const char *) tok->val.str.text);
	literal = build_userdef_literal (get_identifier (suffix),
					 string, OT_NONE, NULL_TREE);
	*value = literal;
      }
      break;

    case CPP_STRING:
    case CPP_WSTRING:
    case CPP_STRING16:
    case CPP_STRING32:
    case CPP_UTF8STRING:
      if ((lex_flags & C_LEX_STRING_NO_JOIN) == 0)
	{
	  type = lex_string (tok, value, false,
			     (lex_flags & C_LEX_STRING_NO_TRANSLATE) == 0);
	  break;
	}
      *value = build_string (tok->val.str.len, (const char *) tok->val.str.text);
      break;

    case CPP_PRAGMA:
      *value = build_int_cst (integer_type_node, tok->val.pragma);
      break;

    case CPP_HEADER_NAME:
      *value = build_string (tok->val.str.len, (const char *)tok->val.str.text);
      break;

    case CPP_EMBED:
      *value = make_node (RAW_DATA_CST);
      TREE_TYPE (*value) = integer_type_node;
      RAW_DATA_LENGTH (*value) = tok->val.str.len;
      if (pch_file)
	{
	  /* When writing PCH headers, copy the data over, such that
	     the owner is a STRING_CST.  */
	  int off = 0;
	  if (tok->val.str.len <= INT_MAX - 2)
	    /* See below.  */
	    off = 1;
	  tree owner = build_string (tok->val.str.len + 2 * off,
				     (const char *) tok->val.str.text - off);
	  TREE_TYPE (owner) = build_array_type_nelts (unsigned_char_type_node,
						      tok->val.str.len);
	  RAW_DATA_OWNER (*value) = owner;
	  RAW_DATA_POINTER (*value) = TREE_STRING_POINTER (owner) + off;
	}
      else
	{
	  /* Otherwise add another dummy RAW_DATA_CST as owner which
	     indicates the data is owned by libcpp.  */
	  RAW_DATA_POINTER (*value) = (const char *) tok->val.str.text;
	  tree owner = make_node (RAW_DATA_CST);
	  TREE_TYPE (owner) = integer_type_node;
	  RAW_DATA_LENGTH (owner) = tok->val.str.len;
	  RAW_DATA_POINTER (owner) = (const char *) tok->val.str.text;
	  if (tok->val.str.len <= INT_MAX - 2)
	    {
	      /* The preprocessor surrounds at least smaller CPP_EMBEDs
		 in between CPP_NUMBER CPP_COMMA before and
		 CPP_COMMA CPP_NUMBER after, so the actual libcpp buffer
		 holds those 2 extra bytes around it.  Don't do that if
		 CPP_EMBED is at the maximum ~ 2GB size.  */
	      RAW_DATA_LENGTH (owner) += 2;
	      RAW_DATA_POINTER (owner)--;
	    }
	  RAW_DATA_OWNER (*value) = owner;
	}
      break;

      /* This token should not be visible outside cpplib.  */
    case CPP_MACRO_ARG:
      gcc_unreachable ();

    /* CPP_COMMENT will appear when compiling with -C.  Ignore, except
       when it is a FALLTHROUGH comment, in that case set
       PREV_FALLTHROUGH flag on the next non-comment token.  */
    case CPP_COMMENT:
      if (tok->flags & PREV_FALLTHROUGH)
	{
	  do
	    {
	      tok = get_token (parse_in, loc);
	      type = tok->type;
	    }
	  while (type == CPP_PADDING || type == CPP_COMMENT);
	  add_flags |= PREV_FALLTHROUGH;
	  goto retry_after_at;
	}
      goto retry;

    default:
      *value = NULL_TREE;
      break;
    }

  if (cpp_flags)
    *cpp_flags = tok->flags | add_flags;

  timevar_pop (TV_CPP);"}

